cerpt":"Let's Roll the Ball!","why":"No matching-title warning exists."}],"final_value":{},"provenance":"deterministic_evidence"},{"metadata_id":"877e16df-b61b-4cef-9729-4de184b8d385","lesson_id":"df1059ee-c34b-4ff2-90c4-14c5e609a847","decision_key":"communication","classification":"communication_mode_irrelevant","requires_human":false,"decision_status":"resolved_deterministic","plain_language_summary":"Success is an action or receptive response; expressive communication mode is not the learning target.","recommendation":null,"rationale":"The goal is completed through an action or receptive response.","evidence":[{"field":"goal","excerpt":"Child will participate in one simple turn-taking exchange with support.","why":"The goal is completed through an action or receptive response."}],"final_value":{"response_requirement":"receptive_or_action"},"provenance":"deterministic_evidence"},{"metadata_id":"877e16df-b61b-4cef-9729-4de184b8d385","lesson_id":"df1059ee-c34b-4ff2-90c4-14c5e609a847","decision_key":"safety_material","classification":"no_safety_decision","requires_human":false,"decision_status":"resolved_deterministic","plain_language_summary":"Materials and optional supports are explicitly described; restriction matching can occur without labeling the lesson universally unsafe.","recommendation":null,"rationale":"No ambiguous required safety-sensitive material appears.","evidence":[{"field":"materials","excerpt":"Ball Car Favorite toy","why":"No ambiguous required safety-sensitive material appears."}],"final_value":{"food_use":"not_present","small_object_use":"not_required","physical_contact":"not_required","sound":"not_loud","descriptors":{"water":false,"movement":false,"music":false}},"provenance":"deterministic_evidence"},{"metadata_id":"877e16df-b61b-4cef-9729-4de184b8d385","lesson_id":"df1059ee-c34b-4ff2-90c4-14c5e609a847","decision_key":"prerequisite","classification":"no_prerequisite_deterministic","requires_human":false,"decision_status":"resolved_deterministic","plain_language_summary":"This is a beginning lesson and does not require an earlier capability.","recommendation":null,"rationale":"Beginning-stage entry point.","evidence":[{"field":"stage","excerpt":"Beginning 1","why":"Beginning-stage entry point."}],"final_value":{"relationship":"none"},"provenance":"deterministic_evidence"},{"metadata_id":"877e16df-b61b-4cef-9729-4de184b8d385","lesson_id":"df1059ee-c34b-4ff2-90c4-14c5e609a847","decision_key":"mastery","classification":"specific_group_deterministic","requires_human":false,"decision_status":"resolved_deterministic","plain_language_summary":"The mastery group exactly matches the specific target capability and does not suppress unrelated skills.","recommendation":null,"rationale":"Target and mastery group are identical.","evidence":[{"field":"target/mastery","excerpt":"social.turn_taking / social.turn_taking","why":"Target and mastery group are identical."}],"final_value":{"mastery_group":"social.turn_taking"},"provenance":"deterministic_evidence"},{"metadata_id":"877e16df-b61b-4cef-9729-4de184b8d385","lesson_id":"df1059ee-c34b-4ff2-90c4-14c5e609a847","decision_key":"duplicate_progression","classification":"none","requires_human":false,"decision_status":"resolved_deterministic","plain_language_summary":"No duplicate or progression candidate exists.","recommendation":null,"rationale":"No matching-title warning exists.","evidence":[{"field":"title","excerpt":"My Turn, Your Turn","why":"No matching-title warning exists."}],"final_value":{},"provenance":"deterministic_evidence"}]$audit$::jsonb) as x(metadata_id uuid,lesson_id uuid,decision_key text,classification text,requires_human boolean,decision_status text,plain_language_summary text,recommendation text,rationale text,evidence jsonb,final_value jsonb,provenance text))
update public.lesson_personalization_review_decisions d set classification=a.classification,requires_human=a.requires_human,decision_status=a.decision_status,plain_language_summary=a.plain_language_summary,recommendation=a.recommendation,rationale=a.rationale,evidence=a.evidence,final_value=a.final_value,provenance=a.provenance,reviewer_user_id=null,reviewed_at=null,review_reason=null,updated_at=now() from audited a where d.metadata_id=a.metadata_id and d.lesson_id=a.lesson_id and d.decision_key=a.decision_key and d.decision_status in ('unresolved','resolved_deterministic');
alter table public.lesson_personalization_review_decisions enable trigger lesson_personalization_review_decision_history_trigger;

alter table public.lesson_personalization_metadata disable trigger lesson_personalization_metadata_history_trigger;
update public.lesson_personalization_metadata meta set communication_reviewed=not exists(select 1 from public.lesson_personalization_review_decisions d where d.metadata_id=meta.id and d.decision_category='communication' and d.decision_status not in ('resolved_deterministic','human_confirmed','human_edited')),safety_reviewed=not exists(select 1 from public.lesson_personalization_review_decisions d where d.metadata_id=meta.id and d.decision_category='safety_material' and d.decision_status not in ('resolved_deterministic','human_confirmed','human_edited')),mastery_reviewed=not exists(select 1 from public.lesson_personalization_review_decisions d where d.metadata_id=meta.id and d.decision_category='mastery' and d.decision_status not in ('resolved_deterministic','human_confirmed','human_edited')),duplicate_reviewed=not exists(select 1 from public.lesson_personalization_review_decisions d where d.metadata_id=meta.id and d.decision_category='duplicate_progression' and d.decision_status not in ('resolved_deterministic','human_confirmed','human_edited')),prerequisite_review_state=case when exists(select 1 from public.lesson_personalization_review_decisions d where d.metadata_id=meta.id and d.decision_category='prerequisite' and d.decision_status='unresolved') then 'ambiguous' when exists(select 1 from public.lesson_personalization_review_decisions d where d.metadata_id=meta.id and d.decision_category='prerequisite' and d.classification='no_prerequisite_deterministic') then 'no_prerequisite_deterministic' else 'rejected' end,prerequisite_skill_codes='{}'::text[],human_decision_summary=(select jsonb_object_agg(d.decision_key,jsonb_build_object('classification',d.classification,'status',d.decision_status,'provenance',d.provenance,'final_value',d.final_value,'recommendation',d.recommendation,'evidence',d.evidence)) from public.lesson_personalization_review_decisions d where d.metadata_id=meta.id),last_review_method='phase9f6b_evidence_audit' where exists(select 1 from public.lesson_personalization_review_decisions d where d.metadata_id=meta.id);
alter table public.lesson_personalization_metadata enable trigger lesson_personalization_metadata_history_trigger;

-- Phase 9F.6 corrective migration: remove PL/pgSQL record/alias ambiguity.
create or replace function public.review_production_lesson_metadata_decision(p_decision_id uuid,p_outcome text,p_final_value jsonb default '{}'::jsonb,p_reason text default null,p_review_method text default 'production_review')
returns public.lesson_personalization_review_decisions language plpgsql security definer set search_path=pg_catalog,public as $$
declare d public.lesson_personalization_review_decisions;metadata_row public.lesson_personalization_metadata;l public.lesson_library;skill text;
begin
  if not public.is_app_admin() then raise exception 'Admin authorization required'; end if;
  select * into d from public.lesson_personalization_review_decisions where id=p_decision_id for update;
  if d.id is null then raise exception 'Decision not found'; end if;
  select * into l from public.lesson_library where id=d.lesson_id;
  if l.quality_status<>'approved' or not l.is_active then raise exception 'Decision is not for a current production lesson'; end if;
  if (d.decision_category='communication' and p_outcome not in ('confirm_recommendation','speech_required','alternate_modes','needs_more_review','needs_content_review','edited'))
    or (d.decision_category='safety_material' and p_outcome not in ('human_confirmed','needs_more_review','needs_content_review','edited'))
    or (d.decision_category='mastery' and p_outcome not in ('confirm_scope','needs_more_review','needs_content_review','edited'))
    or (d.decision_category='duplicate_progression' and p_outcome not in ('intentional_progression','intentional_variant','likely_duplicate','needs_content_review','needs_more_review','edited'))
  then raise exception 'Invalid outcome for % decision',d.decision_category; end if;
  if p_outcome='needs_content_review' then d.decision_status:='content_dependent';d.provenance:='content_dependent';
  elsif p_outcome='needs_more_review' then d.decision_status:='needs_more_review';d.provenance:='human_confirmed';
  elsif p_outcome in ('edited','human_edited') then d.decision_status:='human_edited';d.provenance:='human_edited';
  else d.decision_status:='human_confirmed';d.provenance:='human_confirmed'; end if;
  if d.decision_category='prerequisite' and p_outcome not in ('required','helpful','not_required','needs_more_review','needs_content_review','edited') then raise exception 'Invalid prerequisite outcome'; end if;
  if d.decision_category='prerequisite' and p_outcome='required' then
    skill:=coalesce(p_final_value->>'skill_code',d.candidate_value->>'suggested_skill_code');
    if skill is null then raise exception 'Required prerequisite needs a skill code'; end if;
    select * into metadata_row from public.lesson_personalization_metadata where id=d.metadata_id;
    if skill=metadata_row.target_skill_code then raise exception 'A target cannot be its own prerequisite'; end if;
  end if;
  perform set_config('app.metadata_review_action',p_review_method,true);
  update public.lesson_personalization_review_decisions set decision_status=d.decision_status,final_value=coalesce(p_final_value,'{}'::jsonb)||jsonb_build_object('outcome',p_outcome),provenance=d.provenance,reviewer_user_id=auth.uid(),reviewed_at=now(),review_reason=p_reason,updated_at=now() where id=d.id returning * into d;
  update public.lesson_personalization_metadata meta set
    communication_reviewed=not exists(select 1 from public.lesson_personalization_review_decisions x where x.metadata_id=meta.id and x.decision_category='communication' and x.decision_status not in ('resolved_deterministic','human_confirmed','human_edited')),
    safety_reviewed=not exists(select 1 from public.lesson_personalization_review_decisions x where x.metadata_id=meta.id and x.decision_category='safety_material' and x.decision_status not in ('resolved_deterministic','human_confirmed','human_edited')),
    mastery_reviewed=not exists(select 1 from public.lesson_personalization_review_decisions x where x.metadata_id=meta.id and x.decision_category='mastery' and x.decision_status not in ('resolved_deterministic','human_confirmed','human_edited')),
    duplicate_reviewed=not exists(select 1 from public.lesson_personalization_review_decisions x where x.metadata_id=meta.id and x.decision_category='duplicate_progression' and x.decision_status not in ('resolved_deterministic','human_confirmed','human_edited')),
    prerequisite_review_state=case when d.decision_category='prerequisite' and p_outcome='required' then 'confirmed' when d.decision_category='prerequisite' and p_outcome in ('helpful','not_required') then 'rejected' when d.decision_category='prerequisite' then 'ambiguous' else meta.prerequisite_review_state end,
    prerequisite_skill_codes=case when d.decision_category='prerequisite' and p_outcome='required' then array[coalesce(p_final_value->>'skill_code',d.candidate_value->>'suggested_skill_code')]::text[] when d.decision_category='prerequisite' and p_outcome in ('helpful','not_required') then '{}'::text[] else meta.prerequisite_skill_codes end,
    human_decision_summary=(select jsonb_object_agg(x.decision_key,jsonb_build_object('classification',x.classification,'status',x.decision_status,'provenance',x.provenance,'final_value',x.final_value,'recommendation',x.recommendation)) from public.lesson_personalization_review_decisions x where x.metadata_id=meta.id),last_review_method=p_review_method
  where meta.id=d.metadata_id;
  return d;
end;$$;
revoke all on function public.review_production_lesson_metadata_decision(uuid,text,jsonb,text,text) from public,anon;
grant execute on function public.review_production_lesson_metadata_decision(uuid,text,jsonb,text,text) to authenticated;


commit;
